const defaults={color:'#f28b58',colorName:'Tangerine',skin:'#edc7a1',hairColor:'#655341',hairStyle:'short',headwear:'none',hatColor:'#7e9c79',outfit:'tee',pantsColor:'#586451',shoesColor:'#465345',eyewear:'none',doubleJump:true,trail:true,speed:5,jump:12,gravity:.5,theme:'meadow',level:0};let settings={...defaults},custom=null;
