const palettes={meadow:{sky:'#e8efde',hill1:'#dce6ca',hill2:'#ceddb8',hill3:'#bccf9f',ground:'#a2b884',top:'#809a61',soil:'#91a776',cloud:'#f6f8ed'},dusk:{sky:'#383e58',hill1:'#505473',hill2:'#626080',hill3:'#767195',ground:'#9a8bad',top:'#bdacc6',soil:'#8c7e9e',cloud:'#787690'},desert:{sky:'#f6e9ce',hill1:'#eddbad',hill2:'#e3ca92',hill3:'#d6b97f',ground:'#c8a56c',top:'#a88751',soil:'#b99963',cloud:'#fff5df'}};
const TILE=25;
function makeLevel(){return {blocks:[],fakeBlocks:[],water:[],stars:[],coins:[],fakeSpikes:[],spikes:[],spawn:{x:75,y:450},goal:null}}
