function normalizeWorld(w){const blocks=new Map();for(const b of w.blocks||w.platforms||[]){for(let y=0;y<Math.ceil(b.h/TILE);y++)for(let x=0;x<Math.ceil(b.w/TILE);x++){let bx=Math.round(b.x/TILE)*TILE+x*TILE,by=Math.round(b.y/TILE)*TILE+y*TILE;blocks.set(bx+','+by,{x:bx,y:by,w:TILE,h:TILE})}}return {blocks:[...blocks.values()],fakeBlocks:(w.fakeBlocks||[]).map(t=>({x:t.x,y:t.y,w:25,h:25})),stars:(w.stars||[]).map(t=>({x:t.x,y:t.y})),water:(w.water||[]).map(t=>({x:t.x,y:t.y,w:25,h:25})),coins:w.coins,fakeSpikes:(w.fakeSpikes||[]).map(t=>({x:t.x,y:t.y})),spikes:w.spikes,spawn:w.spawn,goal:w.goal??null}}
