function screenPoint(e){const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)*1000/r.width,y:(e.clientY-r.top)*600/r.height}}
function worldPoint(e){const s=screenPoint(e);return {x:camera.x+s.x/camera.zoom,y:camera.y+s.y/camera.zoom}}
function goalBox(){return world.goal?{x:world.goal.x-8,y:world.goal.y-8,w:48,h:80}:null}
function persistEdit(){custom=structuredClone(world);coins=world.coins.map(c=>({...c,got:false}));stars=world.stars.map(s=>({...s,got:false}));sync();updateHud();save()}
function selectTool(t){tool=t;$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===t));$('#toolHint').textContent=t==='fakeSpike'?'Paint lighter fake spikes. You can safely pass through them.':t==='star'?'Place a gold star. Collect it to run 80% faster for 5 seconds. Another star refreshes the timer.':t==='fake'?'Paint slightly lighter fake blocks. They look like terrain, but you can walk and fall straight through.':t==='water'?'Paint water blocks. Hold Space, W, or ↑ to swim up. You have 5 seconds of breath; leave the water fully to recover.':t==='goal'?'Click anywhere to move the single finish flag. You can also drag the existing flag.':t==='erase'?'Click or drag to erase blocks, coins, spikes, or the finish flag.':t==='pan'?'Drag the world in any direction. There are no map edges.':'Click or drag to paint 25 × 25 blocks. One block is one small landing space.'}
function editAt(pt,erase=false){let x=Math.floor(pt.x/TILE)*TILE,y=Math.floor(pt.y/TILE)*TILE,key=x+','+y;if(lastCell===key&&!erase)return;lastCell=key;let cell={x,y,w:TILE,h:TILE};if(erase||tool==='erase'){const g=goalBox();if(g&&overlap(cell,g)){world.goal=null;toast('Finish removed. Choose Place finish to add it anywhere.')}else{world.blocks=world.blocks.filter(b=>!overlap(cell,b));world.fakeBlocks=world.fakeBlocks.filter(b=>!overlap(cell,b));world.water=world.water.filter(b=>!overlap(cell,b));world.stars=world.stars.filter(s=>!overlap(cell,{x:s.x-11,y:s.y-11,w:22,h:22}));world.coins=world.coins.filter(c=>!overlap(cell,{x:c.x-9,y:c.y-9,w:18,h:18}));world.fakeSpikes=world.fakeSpikes.filter(s=>!overlap(cell,{...s,w:20,h:20}));world.spikes=world.spikes.filter(s=>!overlap(cell,{...s,w:20,h:20}))}}else if(tool==='block'){world.fakeBlocks=world.fakeBlocks.filter(b=>!overlap(cell,b));world.water=world.water.filter(b=>!overlap(cell,b));if(!world.blocks.some(b=>b.x===x&&b.y===y))world.blocks.push({...cell})}else if(tool==='water'){world.fakeBlocks=world.fakeBlocks.filter(b=>!overlap(cell,b));world.blocks=world.blocks.filter(b=>!overlap(cell,b));if(!world.water.some(b=>b.x===x&&b.y===y))world.water.push({...cell})}else if(tool==='fake'){world.blocks=world.blocks.filter(b=>!overlap(cell,b));world.water=world.water.filter(b=>!overlap(cell,b));if(!world.fakeBlocks.some(b=>b.x===x&&b.y===y))world.fakeBlocks.push({...cell})}else if(tool==='star'){if(!world.stars.some(s=>s.x===x+12&&s.y===y+12))world.stars.push({x:x+12,y:y+12})}else if(tool==='coin'){if(!world.coins.some(c=>Math.abs(c.x-x-12)<1&&Math.abs(c.y-y-12)<1))world.coins.push({x:x+12,y:y+12})}else if(tool==='spike'){world.fakeSpikes=world.fakeSpikes.filter(s=>s.x!==x||s.y!==y);if(!world.spikes.some(s=>s.x===x&&s.y===y))world.spikes.push({x,y})}else if(tool==='fakeSpike'){world.spikes=world.spikes.filter(s=>s.x!==x||s.y!==y);if(!world.fakeSpikes.some(s=>s.x===x&&s.y===y))world.fakeSpikes.push({x,y})}else if(tool==='spawn'){world.spawn={x,y};p.x=x;p.y=y}else if(tool==='goal'){let moving=!!world.goal;world.goal={x,y:y-40};toast(moving?'Finish moved here. There is one finish per world.':'Finish placed. Drag the flag to move it.')}persistEdit()}
function currentGame(){return library.games.find(g=>g.id===library.active)}
function freshGame(){return {id:crypto.randomUUID(),name:'My next adventure',settings:{...defaults},custom:null}}
function loadActiveGame(){const game=currentGame();settings={...defaults,...game.settings};custom=game.custom?structuredClone(game.custom):null;world=normalizeWorld(custom||makeLevel(settings.level));restart();setMode(world.blocks.length||world.water.length?'play':'build');sync()}
function save(changedGameId=library.active){let game=currentGame();game.settings={...settings};game.custom=custom?structuredClone(custom):null;try{const latest=JSON.parse(localStorage.getItem('jumpcraft-library-v1'));const removed=new Set([...(library.deletedIds||[]),...(latest?.deletedIds||[])]);const merged=new Map((latest?.games||[]).filter(g=>g&&typeof g.id==='string'&&typeof g.name==='string'&&!removed.has(g.id)).map(g=>[g.id,g]));for(const g of library.games)if(!removed.has(g.id)&&(g.id===game.id||g.id===changedGameId||!merged.has(g.id))){const stored=merged.get(g.id);if(hasBest(stored)&&(!hasBest(g)||stored.bestTime<g.bestTime))g.bestTime=stored.bestTime;merged.set(g.id,g)}library.games=[...merged.values()];library.deletedIds=[...removed];if(!library.games.length)library.games.push(freshGame());if(!library.games.some(g=>g.id===library.active)){library.active=library.games[0].id;loadActiveGame();game=currentGame()}localStorage.setItem('jumpcraft-library-v1',JSON.stringify(library));$('#saveState').textContent='● Autosaved on this device';$('#menuSaveState').textContent='● All games saved automatically on this device'}catch{$('#saveState').textContent='● Storage unavailable';$('#menuSaveState').textContent='Storage unavailable — export your world to keep a copy.'}$('#currentGame').textContent=currentGame().name}
function flushSave(){if(drag?.kind==='goal')custom=structuredClone(world);save()}
function renderLibrary(){const list=$('#gamesList');list.replaceChildren();for(const game of library.games){const row=document.createElement('button');row.type='button';row.className='game-card'+(game.id===library.active?' active':'');row.setAttribute('aria-current',game.id===library.active?'true':'false');const icon=document.createElement('span');icon.className='game-card-icon';icon.textContent='▦';const detail=document.createElement('span');const title=document.createElement('strong');title.textContent=game.name;const subtitle=document.createElement('small');subtitle.textContent=(game.id===library.active?'Currently open · ':'')+(game.settings?.doubleJump===false?'Single jump':'Double jump')+' · '+(game.custom?'Custom world':'Blank world');if(hasBest(game))subtitle.textContent+=' · Best '+formatTime(game.bestTime);detail.append(title,subtitle);const arrow=document.createElement('span');arrow.textContent=game.id===library.active?'●':'↗';row.append(icon,detail,arrow);row.onclick=()=>switchGame(game.id);const entry=document.createElement('div');entry.className='game-entry';const options=document.createElement('button');options.type='button';options.className='world-options';options.textContent='⚙';options.setAttribute('aria-label','Options for '+game.name);options.setAttribute('aria-controls','worldOptions');options.onclick=()=>openWorldOptions(game.id);const remove=document.createElement('button');remove.type='button';remove.className='delete-game';remove.textContent='Delete';remove.setAttribute('aria-label','Delete '+game.name);remove.onclick=()=>requestDeleteGame(game.id);entry.append(row,options,remove);list.append(entry)}$('#renameInput').value=(library.games.find(g=>g.id===renamingGameId)||currentGame()).name;$('#gameCount').textContent=library.games.length+' saved '+(library.games.length===1?'game':'games')}
let pendingDeleteId=null,renamingGameId=null;
function hasBest(game){return !!game&&Number.isFinite(game.bestTime)&&game.bestTime>=0}
function recordRun(){const complete=coins.every(c=>c.got);let improved=false;if(complete){const game=currentGame();if(!hasBest(game)||elapsed<game.bestTime){game.bestTime=elapsed;improved=true}save()}return {complete,improved}}
function finishRun(){if(!playing)return;playing=false;const run=recordRun();$('#resultTitle').textContent=run.complete?(run.improved?'New best time!':'World complete!'):'Run finished';$('#result').textContent=coins.filter(c=>c.got).length+' / '+coins.length+' coins · '+formatTime(elapsed)+' · '+deaths+' falls';$('#recordResult').textContent=run.complete?'All coins collected · Best '+formatTime(currentGame().bestTime):'No record saved. Collect every coin and reach the finish to qualify.';$('#overlay').hidden=false;updateHud();tone(980)}
