function openWorldOptions(id){const game=library.games.find(g=>g.id===id);if(!game)return;renamingGameId=id;$('#worldOptions').hidden=false;$('#renameLabel').textContent='Rename “'+game.name+'”';$('#renameInput').value=game.name;$('#renameInput').focus()}
function renameWorld(id,name){const next=String(name||'').trim().slice(0,60);if(!next)return false;save();const game=library.games.find(g=>g.id===id);if(!game)return false;game.name=next;save(id);closeWorldOptions();renderLibrary();toast('Game renamed.');return true}

