function waterState(){return {wet:world.water.some(t=>overlap(p,t)),submerged:world.water.some(t=>overlap({x:p.x+5,y:p.y+2,w:15,h:12},t))}}
function updateBreath(){const state=waterState();p.inWater=state.wet;if(state.wet)p.breath=Math.max(0,p.breath-1/60);else if(!state.wet)p.breath=Math.min(5,p.breath+.5/60);if(p.breath<=1e-8){deaths++;restart(false);tone(140);toast('Out of breath! Get fully out of the water to recover.');return true}return false}

