if(p.y>deathFloor()||world.spikes.some(s=>overlap(p,{...s,w:20,h:20}))){deaths++;restart(false);tone(160)}
for(const star of stars)if(!star.got&&overlap(p,{x:star.x-11,y:star.y-11,w:22,h:22})){star.got=true;speedBoostFrames=300;tone(1040);toast('Star power! Speed boosted for 5 seconds.')}
